// --- prototypes generated by arduino_sim.py (the Arduino IDE/Tinkercad do the same) ---
void setup();
void loop();
// millis lab, Exercise 1: elapsed time in ms, in s, in m:ss, printed every 2 s without delay()
unsigned long previous = 0;
void setup() { Serial.begin(9600); }
void loop() {
  unsigned long now = millis();
  if (now - previous >= 2000) {
    previous = now;
    Serial.print("ms: "); Serial.print(now);                    // Q1
    Serial.print("   s: "); Serial.print(now / 1000);           // Q2
    unsigned long s = now / 1000;
    Serial.print("   m:ss: "); Serial.print(s / 60); Serial.print(':');   // Q3
    if (s % 60 < 10) Serial.print('0');
    Serial.println(s % 60);
  }
}
